"""Exact logarithmic mass on even Juggler fibres and finite Collatz codes.

Products of rational numbers certify sums of logarithmic weights without
floating point. See docs/problems/juggler_code_mass_transport.md for proofs.
"""

from __future__ import annotations

from fractions import Fraction
from math import isqrt, prod
from typing import Iterable

from research.juggler_sequence.collatz_bridge import juggler


def weight_ratio(n: int) -> Fraction:
    """exp(w(n)), where w(n) = log((e+1)/(e-1)), e = next even >= n."""
    if n < 1:
        raise ValueError("n must be positive")
    even = n + n % 2
    return Fraction(even + 1, even - 1)


def mass_product(values: Iterable[int]) -> Fraction:
    """exp(sum w(n)); repeated values count repeatedly."""
    return prod((weight_ratio(n) for n in values), start=Fraction(1))


def even_fibre(target: int) -> range:
    """Every positive even n with J(n)=target, in increasing order."""
    if target < 1:
        raise ValueError("target must be positive")
    return range(target * target + target % 2, (target + 1) ** 2, 2)


def partial_fibre_ratio(target: int, cutoff: int) -> Fraction:
    """Closed form for exp(sum_{n in E(target), n <= cutoff} w(n))."""
    if target < 1 or cutoff < 0:
        raise ValueError("require positive target and nonnegative cutoff")
    first = target * target + target % 2
    last = min(cutoff, (target + 1) ** 2 - 1)
    last -= last % 2
    return Fraction(last + 1, first - 1) if last >= first else Fraction(1)


def code_residue(n: int, depth: int) -> int:
    """H(n) mod 2**depth for the minus code, using actual Juggler parities.

    The inverse branch expansion is sum 2**position/3**odd_count. Only
    depth steps are evaluated; no termination assumption is made.
    """
    if n < 1 or depth < 0:
        raise ValueError("require positive n and nonnegative depth")
    modulus = 1 << depth
    residue, odd_count = 0, 0
    for position in range(depth):
        if n % 2:
            odd_count += 1
            residue += (1 << position) * pow(3**odd_count, -1, modulus)
        n = juggler(n)
    return residue % modulus


def coded_products(cutoff: int, depth: int) -> dict[int, Fraction]:
    """Products exp(nu_cutoff(cylinder)) grouped by H modulo 2**depth."""
    if cutoff < 0 or depth < 0:
        raise ValueError("cutoff and depth must be nonnegative")
    result: dict[int, Fraction] = {}
    for n in range(1, cutoff + 1):
        residue = code_residue(n, depth)
        result[residue] = result.get(residue, Fraction(1)) * weight_ratio(n)
    return result


def even_generations(root: int, depth: int) -> tuple[tuple[int, ...], ...]:
    """Small complete inverse generations; sizes grow very quickly."""
    if root < 1 or depth < 0:
        raise ValueError("require positive root and nonnegative depth")
    levels = [(root,)]
    for _ in range(depth):
        levels.append(tuple(n for m in levels[-1] for n in even_fibre(m)))
    return tuple(levels)


def main() -> None:
    """Bounded exact checks and a small, readable report; no output files."""
    for m in range(1, 1001):
        assert mass_product(even_fibre(m)) == weight_ratio(m)
    print("Exact fibre product identity: targets 1..1000 passed")
    checks = 0
    for cutoff in range(1, 257):
        m = isqrt(cutoff)
        for depth in range(5):
            source = coded_products(cutoff, depth + 1)
            parents = coded_products(m - 1, depth)
            boundary = code_residue(m, depth)
            for residue in range(1 << depth):
                expected = parents.get(residue, Fraction(1))
                if residue == boundary:
                    expected *= partial_fibre_ratio(m, cutoff)
                assert source.get(2 * residue, Fraction(1)) == expected
                checks += 1
    print(f"Exact coded-cutoff cylinder identities: {checks} passed")
    for depth, level in enumerate(even_generations(2, 3)):
        product = mass_product(level)
        assert product == 3
        print(f"depth={depth}, count={len(level)}, min={min(level)}, "
              f"max={max(level)}, code={2 ** (depth + 1)}, exp(mass)={product}")


if __name__ == "__main__":
    main()

tests/research/juggler_sequence/test_cod:
"""Independent forward checks of the fibre and coded-cutoff mass laws."""

from collections import Counter
from fractions import Fraction
from math import isqrt, log

import pytest

from research.juggler_sequence.code_mass_transport import (
    code_residue,
    coded_products,
    even_fibre,
    even_generations,
    mass_product,
    partial_fibre_ratio,
    weight_ratio,
)
from research.juggler_sequence.collatz_bridge import juggler


def test_forward_fibres_and_exact_products():
    # The forward map supplies the sets, independently of the inverse formula.
    fibres = {m: [] for m in range(1, 151)}
    for n in range(2, 151**2, 2):
        fibres[juggler(n)].append(n)
    for target, values in fibres.items():
        assert values == list(even_fibre(target))
        assert mass_product(values) == weight_ratio(target)


def test_reciprocal_comparison_and_total_mass():
    for n in range(1, 1001):
        w = log(weight_ratio(n))
        assert 1 / n <= w <= 4 / n
        expected = (n + 1) ** 2 if n % 2 == 0 else n * (n + 2)
        assert mass_product(range(1, n + 1)) == expected


@pytest.mark.parametrize("target", [1, 2, 3, 4, 5, 16, 17])
def test_partial_fibres_including_empty_and_saturated(target):
    for cutoff in range(target**2 - 1, (target + 1) ** 2 + 2):
        actual = mass_product(n for n in range(2, cutoff + 1, 2)
                              if juggler(n) == target)
        assert partial_fibre_ratio(target, cutoff) == actual


def test_code_by_independent_signed_collatz_forward_parities():
    for depth in range(7):
        for n in range(1, 101):
            source, coded = n, code_residue(n, depth)
            for _ in range(depth):
                assert source % 2 == coded % 2
                source = juggler(source)
                coded = coded // 2 if coded % 2 == 0 else (3 * coded - 1) // 2


def test_exact_cylinder_cutoff_transport():
    for cutoff in range(1, 101):
        m = isqrt(cutoff)
        for depth in range(5):
            sources = coded_products(cutoff, depth + 1)
            parents = coded_products(m - 1, depth)
            boundary = code_residue(m, depth)
            for residue in range(1 << depth):
                expected = parents.get(residue, Fraction(1))
                if residue == boundary:
                    expected *= partial_fibre_ratio(m, cutoff)
                assert sources.get(2 * residue, Fraction(1)) == expected


def test_raw_multiplicity_is_the_parent_height_moment():
    for cutoff in range(1, 101):
        m = isqrt(cutoff)
        for depth in range(4):
            actual = Counter(code_residue(n, depth + 1)
                             for n in range(1, cutoff + 1))
            predicted = Counter()
            for parent in range(1, m):
                predicted[code_residue(parent, depth)] += parent + 1 - parent % 2
            predicted[code_residue(m, depth)] += sum(
                1 for n in range(2, cutoff + 1, 2) if isqrt(n) == m
            )
            for residue in range(1 << depth):
                assert actual[2 * residue] == predicted[residue]


def test_known_forest_is_disjoint_and_carries_constant_mass():
    seen = set()
    for depth, level in enumerate(even_generations(2, 3)):
        assert len(level) == len(set(level))
        assert not seen.intersection(level)
        seen.update(level)
        assert mass_product(level) == 3
        for n in level:
            assert 2 ** (2**depth) <= n < 3 ** (2**depth)
            value = n
            for _ in range(depth + 1):
                assert value % 2 == 0
                value = juggler(value)
            assert value == 1
            # These itineraries end at the fixed point H(1)=1 exactly.
            assert code_residue(n, depth + 3) == 2 ** (depth + 1)


def test_code_collision_does_not_determine_odd_source_production():
    assert juggler(16) == juggler(18) == 4
    assert juggler(4) == 2 and juggler(2) == 1
    assert code_residue(16, 8) == code_residue(18, 8) == 8
    odd_sources = {target: [n for n in range(1, 21, 2) if juggler(n) == target]
                   for target in (16, 18)}
    assert odd_sources == {16: [], 18: [7]}
    # Larger odd starts already overshoot both targets, by monotonicity.
    assert juggler(21) > 18


@pytest.mark.parametrize("function,args", [
    (weight_ratio, (0,)), (even_fibre, (0,)),
    (partial_fibre_ratio, (1, -1)), (code_residue, (0, 1)),
    (code_residue, (1, -1)), (coded_products, (-1, 0)),
    (even_generations, (0, 1)),
])
def test_invalid_domains(function, args):
    with pytest.raises(ValueError):
        function(*args)
